import time
chunks = []
try:
    while True:
        chunks.append(bytearray(50 * 1024 * 1024))  # 50MB steps
        for i in range(0, len(chunks[-1]), 4096):
            chunks[-1][i] = 1
        time.sleep(0.05)
except MemoryError:
    while True:
        time.sleep(1)
